import{_ as h,c as t,a as p,o as i}from"./app-B8biWd5G.js";const c={};function a(g,n){return i(),t("div",null,[...n[0]||(n[0]=[p('<h1 id="javascript" tabindex="-1"><a class="header-anchor" href="#javascript"><span>JavaScript</span></a></h1><p>🌟 JavaScript</p><p>Chào mừng đến với thế giới JavaScript! 🚀</p><p>JavaScript không chỉ là một ngôn ngữ lập trình – nó là linh hồn của web, là cầu nối giữa ý tưởng và trải nghiệm người dùng, là thứ giúp những trang web đơn giản trở nên sống động, tương tác và đầy cảm xúc.</p><p>Nếu bạn đang đọc những dòng này, nghĩa là bạn đang bắt đầu một hành trình đặc biệt — hành trình trở thành lập trình viên JavaScript thực thụ.</p><p>🌱 Vì sao JavaScript lại tuyệt vời?</p><p>✨ Dễ bắt đầu, phù hợp cho mọi cấp độ</p><p>🌍 Chạy khắp mọi nơi: trình duyệt, server (Node.js), mobile, desktop</p><p>⚡ Sức mạnh linh hoạt từ ứng dụng nhỏ đến hệ thống lớn</p><p>🎨 Giúp tạo ra UI sống động, hiệu ứng, animation</p><p>🧠 Là nền tảng chính của hầu hết framework hiện đại như Vue, React, Angular</p><p>Khi bạn hiểu JavaScript — bạn có thể làm được hầu như mọi thứ trên thế giới lập trình.</p><p>🚀 Trang tài liệu này dành cho ai?</p><p>✔ Những bạn bắt đầu học lập trình ✔ Người muốn hiểu sâu bản chất JavaScript ✔ Developer đang muốn nâng level ✔ Những ai thích xây dựng sản phẩm thực tế</p><p>Tài liệu được viết theo phong cách:</p><p>Ngắn – gọn – dễ hiểu</p><p>Minh hoạ bằng ví dụ trực quan</p><p>Giải thích bản chất thực sự (không chỉ công thức)</p><p>Phù hợp để tự học hoặc nâng cao kỹ năng</p><p>🎯 Bạn sẽ học được gì?</p><p>Cơ bản quan trọng nhất của ngôn ngữ</p><p>Tư duy lập trình hiện đại</p><p>Closure, Scope, Hoisting</p><p>Promise, Async/Await</p><p>DOM, sự kiện, thao tác giao diện</p><p>Object, Prototype, Class</p><p>Tips &amp; best-practice khi code thực tế</p><p>Mỗi phần đều được trình bày rõ ràng, nhiều ví dụ, dễ nhớ.</p><p>❤️ Một lời nhắn gửi</p><p>Học lập trình không phải là một cuộc đua tốc độ. Đó là hành trình trưởng thành, từng bước khám phá và tạo ra giá trị. Hãy học với tâm thế thoải mái — rồi bạn sẽ thấy JavaScript cực kỳ thú vị.</p><p>Nếu bạn gặp vấn đề nào trong quá trình học, đừng ngại hỏi. Chúng ta là cộng đồng và cùng nhau tiến bộ.</p>',31)])])}const e=h(c,[["render",a]]),o=JSON.parse('{"path":"/javascript/","title":"JavaScript","lang":"vi-VN","frontmatter":{},"git":{"updatedTime":1764836967000,"contributors":[{"name":"chinhyeunghe","username":"chinhyeunghe","email":"chinhdd.ph28756@gmail.com","commits":1,"url":"https://github.com/chinhyeunghe"}],"changelog":[{"hash":"394d881b28613968c9400884c595d4a346d86e9e","time":1764836967000,"email":"chinhdd.ph28756@gmail.com","author":"chinhyeunghe","message":"done push project"}]},"filePathRelative":"javascript/README.md"}');export{e as comp,o as data};
